$passed = 0; $failed = 0;
function check(bool $condition, string $message = 'Assertion failed'): void { if (!$condition) throw new RuntimeException($message); }
function same(mixed $expected, mixed $actual): void { if ($expected !== $actual) throw new RuntimeException('Expected '.var_export($expected,true).'; got '.var_export($actual,true)); }
function raises(string $class, callable $body): Throwable { try { $body(); } catch (Throwable $e) { if ($e instanceof $class) return $e; throw new RuntimeException("Expected $class, got ".get_class($e).': '.$e->getMessage(),0,$e); } throw new RuntimeException("Expected $class, no exception thrown"); }
function test(string $name, callable $body): void { global $passed,$failed; $start=hrtime(true); try { $body(); $passed++; printf("PASS %-48s %.3fs\n",$name,(hrtime(true)-$start)/1e9); } catch(Throwable $e) { $failed++; fprintf(STDERR,"FAIL %s: %s\n%s\n",$name,$e,$e->getTraceAsString()); } }
function run(callable $body): mixed { return Async::run($body); }
