test('semaphore capacity and FIFO',fn()=>run(function(){ $s=new Semaphore(2);$active=0;$max=0;$order=[];$tasks=[];for($i=0;$i<20;$i++)$tasks[]=Async::spawn(function()use($s,&$active,&$max,&$order,$i){return $s->withPermit(function()use(&$active,&$max,&$order,$i){$active++;$max=max($max,$active);$order[]=$i;Async::sleep(.001);$active--;});});Async::gather($tasks);same(2,$max);same(range(0,19),$order);raises(LogicException::class,$s->release(...));}));
