test('bounded queue contention and join',fn()=>run(function(){ $q=new Queue(3);$sum=0;Async::taskGroup(function($g)use($q,&$sum){for($p=0;$p<3;$p++)$g->spawn(function()use($q){for($i=0;$i<100;$i++)$q->put($i);});for($c=0;$c<3;$c++)$g->spawn(function()use($q,&$sum){for($i=0;$i<100;$i++){$sum+=$q->get();$q->taskDone();Async::sleep(0);}});});$q->join();same(14850,$sum);$q->close();raises(QueueClosedException::class,$q->get(...));}));
