test('cancelled queue writer and close',fn()=>run(function(){ $q=new Queue(1);$q->put(1);$t=Async::spawn(fn()=>$q->put(2));Async::sleep(0);$t->cancel();same(1,$q->get());$q->taskDone();raises(CancelledException::class,$t->await(...));same(0,$q->count());$q->close();$q->join();}));
