test('file operations binary, empty, metadata, cleanup',fn()=>run(function()use($tmp){$p="$tmp/a";same(4,Files::write($p,"a\0bc")->await());same("a\0bc",Files::read($p)->await());Files::append($p,'d')->await();same(5,Files::stat($p)->await()['size']);Files::copy($p,"$tmp/b")->await();Files::rename("$tmp/b","$tmp/c")->await();check(Files::exists("$tmp/c")->await());same(false,Files::exists("$tmp/missing")->await());raises(OperationException::class,fn()=>Files::copy($p,$p)->await());same(5,Files::stat($p)->await()['size']);Files::write("$tmp/empty",'')->await();same('',Files::read("$tmp/empty")->await());Files::mkdir("$tmp/dir")->await();Files::rmdir("$tmp/dir")->await();check(in_array('a',Files::entries($tmp)->await(),true));raises(OperationException::class,fn()=>Files::read("$tmp/no")->await());}));
