test('SQLite bindings, transaction rollback, queue order',fn()=>run(function()use($tmp){$db=Connection::open("$tmp/sqlite.db")->await();$db->execute('create table t(id integer primary key, name text)')->await();$s=$db->prepare('insert into t(name) values (?)');$tasks=[];for($i=0;$i<40;$i++)$tasks[]=$s->execute(["name$i"]);Async::gather($tasks);same(40,$db->query('select count(*) as n from t')->await()[0]['n']);raises(DomainException::class,fn()=>$db->transaction(function($db){$db->query('insert into t(name) values (?)',['rollback'])->await();throw new DomainException();})->await());same(40,$db->query('select count(*) as n from t')->await()[0]['n']);$db->beginTransaction()->await();$db->query('insert into t(name) values (?)',["a\0b"])->await();$db->commit()->await();same("a\0b",$db->query('select name from t where id=?',[41])->await()[0]['name']);raises(OperationException::class,fn()=>$db->query('select ?',[1,2])->await());raises(OperationException::class,fn()=>$db->query('select 1; select 2')->await());$db->close()->await();}));
test('SQLite cancellation and loop responsiveness',fn()=>run(function(){ $db=Connection::open(':memory:')->await();$task=$db->query('WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<100000000) SELECT sum(x) FROM c');Async::sleep(.01);$start=Scheduler::now();$task->cancel();raises(CancelledException::class,$task->await(...));check(Scheduler::now()-$start<.5);same(1,$db->query('select 1 as n')->await()[0]['n']);$db->close()->await();}));
