test('process workers, crash recovery, timeout, registry',fn()=>run(function()use($tmp){ $pool=new ProcessPool(2,__DIR__.'/fixtures/jobs.php');try{same(5050,$pool->submit('sum',[100])->await());raises(WorkerException::class,fn()=>$pool->submit('missing')->await());raises(WorkerException::class,fn()=>$pool->submit('fail')->await());raises(WorkerException::class,fn()=>$pool->submit('crash')->await());same(55,$pool->submit('sum',[10])->await());raises(TimeoutException::class,fn()=>$pool->submit('delay',[500000],.01)->await());same(['nested'=>[1,true,null]],$pool->submit('echo',[['nested'=>[1,true,null]]])->await());$jobs=[$pool->submit('cpu',[300000,$tmp.'/cpu-barrier']),$pool->submit('cpu',[300000,$tmp.'/cpu-barrier'])];[$a,$b]=Async::gather($jobs);check($a['pid']!==$b['pid']);same($a['hash'],$b['hash']);check(max($a['start'],$b['start'])<min($a['end'],$b['end']),'CPU jobs did not overlap');}finally{$pool->close();}}));
